{
  "metric": "trips",
  "target_window": "2024-12-21",
  "baseline_window": "2024-12-07, 2024-12-14, 2024-12-28",
  "hypotheses": [
    {
      "id": "H0",
      "kind": "metric",
      "statement": "Total yellow taxi trips on Saturday 21 Dec 2024 were lower than the average of the other three Saturdays in December 2024.",
      "support_if": "Trips on 2024-12-21 < average trips on 2024-12-07, 2024-12-14, 2024-12-28 by a meaningful margin (e.g., >5%).",
      "refute_if": "Trips on 2024-12-21 are within normal variance of the other December Saturdays."
    },
    {
      "id": "H1",
      "kind": "weather",
      "statement": "Snowfall on 2024-12-21 reduced taxi demand compared to other December Saturdays with no snow.",
      "support_if": "snow_mm > 0 on 2024-12-21 and snow_mm = 0 on all baseline Saturdays; trips on 2024-12-21 are lower.",
      "refute_if": "No snow on 2024-12-21, or snow also occurred on baseline days with no trip reduction."
    },
    {
      "id": "H2",
      "kind": "holiday",
      "statement": "Proximity to Christmas (Dec 25) caused a holiday-related demand shift on 2024-12-21, independent of weather.",
      "support_if": "2024-12-21 is a pre-holiday shopping Saturday; trips are higher than baseline due to shopping traffic, or lower due to early travel.",
      "refute_if": "No federal/state holiday on 2024-12-21 or adjacent days per us_holidays; trip pattern matches non-holiday Saturdays."
    },
    {
      "id": "H3",
      "kind": "day_of_week",
      "statement": "The trip count on 2024-12-21 is consistent with typical Saturday seasonality in December, and any deviation is not due to day-of-week effects.",
      "support_if": "Trips on all four December Saturdays follow a consistent weekly pattern; 2024-12-21 is an outlier only if weather/holiday explains it.",
      "refute_if": "Systematic difference in trips by week-of-month (e.g., 3rd Saturday always lower) regardless of weather."
    },
    {
      "id": "H4",
      "kind": "fare_mix",
      "statement": "A shift in fare mix (e.g., fewer long-distance trips) on 2024-12-21 reduced trip revenue but not necessarily trip count; however, if avg_trip_distance dropped, it may indicate weather suppressed longer trips.",
      "support_if": "avg_trip_distance on 2024-12-21 is significantly lower than baseline Saturdays, suggesting shorter trips due to snow.",
      "refute_if": "avg_trip_distance and avg_total_amount are stable across all December Saturdays."
    },
    {
      "id": "H5",
      "kind": "zone_mix",
      "statement": "Snowfall caused a geographic shift in trip origins/destinations (e.g., fewer trips to/from outer boroughs), but this cannot be tested with daily aggregated data.",
      "support_if": "N/A — daily aggregates lack zone detail; this hypothesis is not falsifiable with current tables.",
      "refute_if": "N/A — requires trip-level data with pickup/dropoff zones; not available in whybot.yellow_daily."
    },
    {
      "id": "H6",
      "kind": "data_quality",
      "statement": "Missing or erroneous trip data on 2024-12-21 (e.g., reporting gap due to weather) artificially lowers the trip count.",
      "support_if": "Trip count on 2024-12-21 is implausibly low (e.g., near zero or >2σ below mean) with no corresponding weather/holiday explanation.",
      "refute_if": "Trip count is low but plausible given snowfall; data completeness checks pass (e.g., no nulls, consistent with TLC reporting norms)."
    }
  ],
  "queries": [
    {
      "hypothesis_id": "H0",
      "purpose": "Get daily trip counts for all Saturdays in December 2024 to quantify the metric change: target (2024-12-21) vs baseline (2024-12-07, 2024-12-14, 2024-12-28).",
      "tables": ["whybot.yellow_daily"]
    },
    {
      "hypothesis_id": "H1",
      "purpose": "Get snowfall (snow_mm) for each Saturday in December 2024 to test if snow occurred only on 2024-12-21.",
      "tables": ["whybot.nyc_weather_daily"]
    },
    {
      "hypothesis_id": "H2",
      "purpose": "Check for US holidays on or near each December 2024 Saturday (especially 2024-12-21) using authoritative source.",
      "tables": ["whybot.us_holidays"]
    },
    {
      "hypothesis_id": "H3",
      "purpose": "Confirm day-of-week and week-of-month for each December 2024 Saturday to assess seasonality patterns.",
      "tables": ["TPCDS_DB.date_dim"]
    },
    {
      "hypothesis_id": "H4",
      "purpose": "Get avg_trip_distance and avg_total_amount for each December 2024 Saturday to test fare/distance mix shift on 2024-12-21.",
      "tables": ["whybot.yellow_daily"]
    },
    {
      "hypothesis_id": "H6",
      "purpose": "Assess data quality on 2024-12-21 by checking for nulls, zero trips, or extreme outliers in yellow_daily for that date.",
      "tables": ["whybot.yellow_daily"]
    }
  ],
  "rationale": "The plan quantifies the trip drop on 2024-12-21 vs other Dec Saturdays (H0), then tests snowfall (H1), holiday proximity (H2), day-of-week consistency (H3), fare/distance mix (H4), and data quality (H6). Zone mix (H5) is acknowledged but not queryable with daily aggregates. All queries use only catalog tables, stay within 2024-12-01 to 2024-12-31, and are aggregated to daily level."
}

{
  "sql": "SELECT y.trip_date, w.snow_mm FROM whybot.yellow_daily y JOIN whybot.nyc_weather_daily w ON w.obs_date = y.trip_date JOIN TPCDS_DB.date_dim d ON d.d_date = y.trip_date WHERE d.d_dow = 6 AND y.trip_date BETWEEN DATE '2024-12-01' AND DATE '2024-12-31' ORDER BY y.trip_date",
  "tables_used": [
    "whybot.yellow_daily",
    "whybot.nyc_weather_daily",
    "TPCDS_DB.date_dim"
  ],
  "note": "Snowfall for each Saturday in December 2024; d_dow=6 per TPCDS_DB.date_dim docs (0=Sunday)."
}

{
  "sql": "SELECT y.trip_date, y.trips, w.snow_mm, h.holiday_name, d.d_day_name FROM whybot.yellow_daily y JOIN whybot.nyc_weather_daily w ON w.obs_date = y.trip_date LEFT JOIN whybot.us_holidays h ON h.holiday_date = y.trip_date JOIN TPCDS_DB.date_dim d ON d.d_date = y.trip_date WHERE d.d_dow = 6 AND y.trip_date BETWEEN DATE '2024-12-01' AND DATE '2024-12-31' ORDER BY y.trip_date",
  "tables_used": [
    "whybot.yellow_daily",
    "whybot.nyc_weather_daily",
    "whybot.us_holidays",
    "TPCDS_DB.date_dim"
  ],
  "note": "Shows all December 2024 Saturdays with trips, snowfall, and holiday names from authoritative source"
}

