    },
    {
      "cid": "C2",
      "verdict": "supported",
      "strength": 1.0,
      "reason": "Q3 confirms holiday_name is NULL for all four December Saturdays, including 2024-12-21. No federal/state holiday on or adjacent to that date. This refutes H2 (holiday effect) cleanly."
    },
    {
